import { Injectable } from '@angular/core';
import type { SvgNode } from 'svg-engine/core';
import type { LibraryItem } from '../library-item';
import { LibraryRegistry } from '../library-registry';

/**
 * A single entry in the Shape Library — a named pre-fab vector that
 * builds into an `SvgNode` ready for insertion into the document.
 *
 * **Why a `build()` factory instead of a static `SvgNode`**: every
 * node needs a fresh `id` (UUID, generated by the factory functions in
 * `core/node-factory.ts`); pre-baked nodes would be reused across
 * inserts and clash on id. Factories also let the shape opt into
 * default styling overrides passed by the caller (future enhancement).
 *
 * The factory takes no arguments in v1 — shapes are fixed-visual. To
 * make a shape parametric (e.g., star points), register multiple
 * `ShapeLibraryItem`s with different ids (`shape.star-5`, `shape.star-6`).
 */
export interface ShapeLibraryItem extends LibraryItem {
  /**
   * Build a fresh `SvgNode` for insertion. Each call returns a NEW
   * node with a unique id (the underlying `createPath`/`createRect`/
   * etc. factories handle id generation).
   */
  build(): SvgNode;
}

/**
 * Registry of `ShapeLibraryItem`s — D-048 Shape Library.
 *
 * Consumers (`<svge-shape-library-panel>`) call `items()` to render
 * a grid of clickable thumbnails; clicking dispatches an
 * `InsertNodeCommand` with `item.build()` as the new node.
 *
 * Scope: per-editor via `provideSvgEngineEditorScope()` (D-042) so
 * two editors mounted side-by-side can host different shape catalogs
 * (e.g., a brand-specific library in editor A vs. generic shapes in
 * editor B) without cross-talk.
 */
@Injectable({ providedIn: 'root' })
export class ShapeLibraryService extends LibraryRegistry<ShapeLibraryItem> {}
